Section CANSEC1. Context {rc : runConstT}.

(* [comment removed for export] *)
Definition x2frA (m : amem) (SPA DT WK T nbb maxW minB scl : Z) : Prop :=
  rw_cells asegs m (SPA + 32) [C8 (Z_to_bv 64 (13 * 2^34)); C8 (Z_to_bv 64 scl); C8 (Z_to_bv 64 maxW)]
  /\ rw_cells asegs m (SPA + 72) [C8 (Z_to_bv 64 minB); C8 (Z_to_bv 64 nbb)]
  /\ rw_cells asegs m (SPA + 128) [C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 WK); C8 (Z_to_bv 64 (DT + 8))]
  /\ rw_cells asegs m (SPA + 160) [C8 (Z_to_bv 64 (DT + 7))]
  /\ rw_cells asegs m (SPA + 192) [C8 (Z_to_bv 64 (DT + 27)); C8 (Z_to_bv 64 (DT + 20)); C8 (Z_to_bv 64 (DT + 35));
                                   C8 (Z_to_bv 64 (DT + 28)); C8 (Z_to_bv 64 (DT + 12)); C8 (Z_to_bv 64 (DT + 19));
                                   C8 (Z_to_bv 64 (DT + 11)); C8 (Z_to_bv 64 (DT + 4)); C8 (Z_to_bv 64 (DT + 4))]
  /\ rw_cells asegs m (SPA + 584) [C8 (Z_to_bv 64 (WK + 676)); C8 (Z_to_bv 64 (maxW + 1)); C8 (Z_to_bv 64 T);
                                   C8 (Z_to_bv 64 (WK + 736))].

(* [comment removed for export] *)
Definition X2WA (SPA DT : Z) (ncells : nat) : list (Z * Z) :=
  [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (SPA + 88, SPA + 96); (SPA + 104, SPA + 112); (SPA + 152, SPA + 160);
   (SPA + 168, SPA + 192); (SPA + 264, SPA + 584); (SPA + 616, SPA + 720)].

(* [comment removed for export] *)
Definition x2fA_inv (m0 m1 : amem) (SPA DT WK T nbb maxW minB scl : Z) (js jt : list byte) (sorted : list (option Z))
    (ncells : nat) (dt : list (option deltX2)) : Prop :=
  u8arr asegs m1 (DT + 4) (X2M.ox2 jt dt) /\ length dt = ncells
  /\ bytes_at asegs m1 (WK + 736) (BM.omerge js sorted)
  /\ x2frA m1 SPA DT WK T nbb maxW minB scl
  /\ munch (X2WA SPA DT ncells) m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.

(* [comment removed for export] *)
Definition x2placeA (RNG : footprint) (m0 : amem) (SPA DT WK : Z) (js : list byte) (ncells : nat) : Prop :=
  ablk (DT + 4) (DT + 4 + 4 * Z.of_nat ncells) /\ ablk WK (WK + 8704) /\ Z.of_nat ncells <= 4096 /\ zlen js = 256
  /\ (DT + 4 + 4 * Z.of_nat ncells <= WK \/ WK + 8704 <= DT + 4)
  /\ DT + 4 + 4 * Z.of_nat ncells <= SPA /\ WK + 8704 <= SPA /\ KHIGH <= SPA /\ SPA + 832 <= 2^47
  /\ unpoisoned m0 (DT + 4) (DT + 4 + 4 * Z.of_nat ncells) /\ zshadow m0 WK 8704
  /\ rng RNG (DT + 4) (4 * Z.of_nat ncells) /\ rng RNG (shad DT) (nshad (4 + 4 * Z.of_nat ncells + DT mod 8))
  /\ rng RNG WK 8704 /\ rng RNG (shad WK) (nshad (8704 + WK mod 8)) /\ rng RNG SPA 832.

Lemma x2place_appW : forall RNG m0 SPA DT WK js ncells, x2placeA RNG m0 SPA DT WK js ncells -> appW (X2WA SPA DT ncells).
