(* [comment removed for export] *)
Definition x2nextA (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m2 : amem)
    (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word) : machine_state :=
  MS (mkR y1 (Z_to_bv 64 SPA) gp tp y5 y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12 y13 y14 y15 y16 y17 y18 y19
          y20 y21 y22 y23 (Z_to_bv 64 2147450880) y25 y26 y27 y28 y29 y30 y31)
     F (Z_to_bv 64 0x81b08) fc None m2 (seg_rom asegs).

(* [comment removed for export] *)
Definition x2c1A_stmt (pc : Z) (P : Z -> Prop) : Prop :=
  forall (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint)
         (x1 x5 x6 x7 x13 x14 x15 x17 x18 x20 x21 x22 x23 x26 x27 x28 x29 x30 x31 : word)
         (m0 m1 : amem) (DT WK T nbb maxW minB scl b e nb tl start len : Z) (sorted : list (option Z)) (js jt : list byte)
         (ncells : nat) (dt : list (option deltX2)) (r : list (option deltX2) * Z) (Q : machine_state -> Prop),
  P len -> len = 2 ^ (tl - nb) -> 1 <= nb <= tl -> tl <= 12 ->
  fill_for_weight (S (Z.to_nat (e - b))) dt start b e nb tl 0 1 sorted = Ok r ->
  0 <= b <= e -> e <= 256 -> 0 <= start ->
  length jt = (4 * ncells)%nat -> length js = length sorted -> length sorted = 256%nat ->
  (forall i v, nth i sorted None = Some v -> 0 <= v < 256) ->
  x2placeA RNG m0 SPA DT WK js ncells ->
  rw_cells asegs m1 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
  x2fA_inv m0 m1 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt ->
  (forall m2 dt' (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word),
     r = (dt', start + (e - b) * len) -> x2fA_inv m0 m2 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt' ->
     rw_cells asegs m2 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
     munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells)] m1 m2 -> wmono asegs m1 m2 ->
     evtF asegs RNG Q (x2nextA SP SPA gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23
                         y25 y26 y27 y28 y29 y30 y31)) ->
  evtF asegs RNG Q
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 nb) (Z_to_bv 64 (4 * start))
             (Z_to_bv 64 len) x13 x14 x15 (Z_to_bv 64 b) x17 x18 (Z_to_bv 64 (WK + 736 + b)) x20 x21 x22 x23
             (Z_to_bv 64 2147450880) (Z_to_bv 64 start) x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

End CANSEC1.

(* [comment removed for export] *)
Ltac x2lenA := rewrite ?upd_bytes_length by (rewrite ?X2M.ox2_length; cbn [length]; lia); rewrite ?X2M.ox2_length; cbn [length]; lia.

Ltac xhA DT4 ARR q :=
  let SOK := fresh "SOK" in
  pose proof (u8arr_store_ok_n asegs _ DT4 _ q 2 (wa (DT4 + q)) ARR ltac:(lia) ltac:(x2lenA) eq_refl) as SOK;
  zstep;
  lazymatch goal with
  | |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ (wa ?E) _) _) => replace E with (DT4 + q) by lia
  | |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ (Z_to_bv 64 ?E) _) _) => replace E with (DT4 + q) by lia
  end;
  lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ _ (le2 ?x)) _) =>
    match goal with H : le2 x = [_; _] |- _ => rewrite H end
  end;
  lazymatch goal with |- evtF _ _ _ (MS _ _ _ _ _ (write_to_mem _ _ ?bb) _) =>
    let ARR2 := fresh "ARR" in
    pose proof (u8arr_write_bytes asegs _ DT4 _ q bb ARR ltac:(lia) ltac:(x2lenA)) as ARR2;
    clear ARR; store_done; rename ARR2 into ARR
  end.

(* [comment removed for export] *)
Ltac olen := lazymatch goal with
  | |- context [length (X2M.oset2 ?l ?i ?c)] => rewrite (X2M.oset2_length l i c); [olen | olen]
  | _ => lia end.

(* [comment removed for export] *)
Ltac xcellA DT4 ARR u :=
  xhA DT4 ARR (4 * u); xhA DT4 ARR (4 * u + 2);
  replace (Z.to_nat (4 * u)) with (4 * Z.to_nat u)%nat in ARR by lia;
  replace (Z.to_nat (4 * u + 2)) with (4 * Z.to_nat u + 2)%nat in ARR by lia;
  rewrite X2M.ox2_store in ARR by olen.

(* [comment removed for export] *)
Ltac sjoinF2x rY rZ J :=
  lazymatch goal with |- evtF ?segs ?RNG ?Q (MS ?R ?F _ ?fc ?rv ?m ?rom) =>
    let KJ := fresh "KJ" in
    assert (KJ : forall w1 w2 : word, evtF segs RNG Q (MS (@bvmap_set 5 word (Z_to_bv 5 rY) w1
                                                            (@bvmap_set 5 word (Z_to_bv 5 rZ) w2 R)) F (Z_to_bv 64 J) fc rv m rom));
    [ let w1 := fresh "w" in let w2 := fresh "w" in intros w1 w2; simp_regs | ]
  end.
Ltac sjoin_close2x rY rZ :=
  let G := fresh "G" in let G' := fresh "G" in
  zstep; if_cases G; zify_cond G;
  [ zstep; zstep; zstep; if_cases G'; zify_lts G';
    [ lazymatch goal with KJ : forall w1 w2 : word, _ |- _ => let v1 := reg_val rY in let v2 := reg_val rZ in apply (KJ v1 v2) end
    | exfalso; lia ]
  | lazymatch goal with KJ : forall w1 w2 : word, _ |- _ => let v1 := reg_val rY in let v2 := reg_val rZ in apply (KJ v1 v2) end ].

(* [comment removed for export] *)
Ltac clear_ckx := repeat match goal with H : sval _ = 0 \/ _ |- _ => clear H | H : -128 <= sval _ <= 127 |- _ => clear H end.

