(* [comment removed for export] *)
Lemma rep_cells : forall c DE, 0 <= DE < 2^32 -> DE mod 65536 = x2_seq c -> DE / 65536 = x2_nbBits c + 256 * x2_len c ->
  0 <= x2_nbBits c < 256 -> 0 <= x2_len c < 256 ->
  le2 (Z_to_bv 64 (Z.lor ((DE ≪ 32) mod 18446744073709551616) DE)) = [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256)]
  /\ le2 (Z_to_bv 64 (Z.lor ((DE ≪ 32) mod 18446744073709551616) DE ≫ 16)) = [Z_to_bv 8 (x2_nbBits c); Z_to_bv 8 (x2_len c)]
  /\ le2 (Z_to_bv 64 (Z.lor ((DE ≪ 32) mod 18446744073709551616) DE ≫ 32)) = [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256)]
