(* [comment removed for export] *)
Ltac xcellL DT4 ARR u :=
  xhA DT4 ARR (4 * u); xhA DT4 ARR (4 * u + 2);
  replace (Z.to_nat (4 * u)) with (4 * Z.to_nat u)%nat in ARR by lia;
  replace (Z.to_nat (4 * u + 2)) with (4 * Z.to_nat u + 2)%nat in ARR by lia;
  rewrite X2M.ox2_store in ARR by lia;
  lazymatch type of ARR with u8arr _ _ _ (X2M.ox2 _ (X2M.oset2 ?cl ?i ?c)) =>
    let d := fresh "dc" in let L := fresh "LC" in
    assert (L : length (X2M.oset2 cl i c) = length cl) by (apply X2M.oset2_length; lia);
    set (d := X2M.oset2 cl i c) in *; clearbody d
  end.

